exercises.solution:
const students = [
  { name: "Ava", city: "Calgary" },
  { name: "Ben", city: "Calgary" },
  { name: "Cy", city: "Edmonton" },
];
function countByCity(rows) {
  const counts = {};
  for (const r of rows) counts[r.city] = (counts[r.city] || 0) + 1;
  return counts;
}
console.log(countByCity(students));
